mapper.select:
select t.application_id applicationId, t.community_id communityId, t.application_name applicationName,
t.bill_month billMonth, t.config_id configId, t.fee_name feeName, t.state state,
t.audit_user_id auditUserId, t.audit_user_name auditUserName, t.audit_time auditTime,
t.audit_remark auditRemark, t.total_count totalCount, t.success_count successCount,
t.error_count errorCount, t.remark, t.create_user_id createUserId, t.create_user_name createUserName,
t.create_time createTime, t.status_cd statusCd
from manual_bill_generation t where 1 = 1

    and t.application_id = #{applicationId}


    and t.community_id = #{communityId}


    and t.state = #{state}


    and t.config_id = #{configId}


    and t.status_cd = #{statusCd}


    and t.bill_month = #{billMonth}


    and t.application_name like concat('%', #{applicationName}, '%')


    and t.create_time >= #{createTimeStart}


    and t.create_time <= #{createTimeEnd}

order by t.create_time desc

    limit #{page}, #{row}

select count(1) count
from manual_bill_generation t where 1 = 1

    and t.application_id = #{applicationId}


    and t.community_id = #{communityId}


    and t.state = #{state}


    and t.config_id = #{configId}


    and t.status_cd = #{statusCd}


    and t.bill_month = #{billMonth}


    and t.application_name like concat('%', #{applicationName}, '%')


    and t.create_time >= #{createTimeStart}


    and t.create_time <= #{createTimeEnd}

select t.detail_id detailId, t.application_id applicationId, t.community_id communityId,
t.config_id configId, t.fee_name feeName, t.rule_id ruleId, t.room_id roomId,
t.room_name roomName, t.owner_id ownerId, t.owner_name ownerName, t.fee_type_cd feeTypeCd,
t.fee_flag feeFlag, t.cur_year_month curYearMonth, t.prepayment_period prepaymentPeriod,
t.amount, t.state, t.error_msg errorMsg, t.create_time createTime, t.status_cd statusCd
from manual_bill_generation_detail t where 1 = 1

    and t.detail_id = #{detailId}


    and t.application_id = #{applicationId}


    and t.community_id = #{communityId}


    and t.state = #{state}


    and t.status_cd = #{statusCd}


    limit #{page}, #{row}

select count(1) count
from manual_bill_generation_detail t where 1 = 1

    and t.detail_id = #{detailId}


    and t.application_id = #{applicationId}


    and t.community_id = #{communityId}


    and t.state = #{state}


    and t.status_cd = #{statusCd}
